  const profiled=await db.collection('system.profile').find({ns:dbName+'.calendarevidencelinks'}).toArray(),linkWrites=profiled.filter(p=>p.op==='update'||p.op==='command'&&(p.command?.findAndModify||p.command?.update)||p.op==='insert');
  assert.equal(linkWrites.length,1,L('marker-in-link-update')+' '+JSON.stringify(linkWrites.map(p=>({op:p.op,cmd:Object.keys(p.command||{})[0]}))));assert.ok(JSON.stringify(linkWrites[0].command).includes(linkOp),L('marker-in-link-update'));
  assert.equal(JSON.stringify(await pay.findOne({_id:pLegacy._id})),JSON.stringify(await pay.findOne({_id:pLegacy._id})),'');assert.equal((await pay.findOne({_id:pLegacy._id})).updatedAt.toISOString(),entry.updatedAt,L('navi-link-entry-untouched'));
  assert.equal((await actOk(job,'link_company_payment_evidence',{paymentId:String(pLegacy._id),evidenceId:String(idA2._id),expectedUpdatedAt:entry.updatedAt},2)).receipt.operationId,linkOp,L('navi-same-slot'));
  assert.equal((await act(job,'link_company_payment_evidence',{paymentId:String(pLegacy._id),evidenceId:String(idA1._id),expectedUpdatedAt:entry.updatedAt},1)).status,409,L('navi-slot-meaning'));
